<?php
namespace App\Http\Controllers\Pelanggan;
use App\Http\Controllers\Controller;
use App\Http\Requests\StoreKendaraanPelangganRequest;
use App\Http\Requests\UpdateKendaraanPelangganRequest;
use App\Models\KendaraanPelanggan;
use App\Services\MasterAuditService;
use App\Services\VehicleGalleryService;
use Illuminate\Http\RedirectResponse;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\View\View;
class KendaraanController extends Controller
{
 private function customer(){ $p=auth()->user()->pelanggan; abort_unless($p,404); return $p; }
 public function index(): View { $p=$this->customer(); $ownership=app(\App\Services\VerifiedCarOwnershipService::class); $vehicles=$ownership->verifiedVehiclesFor((int)$p->id_pelanggan); $vehicles->each(fn (KendaraanPelanggan $vehicle) => $vehicle->load(['penjualan.mobil','pesanan'])); $page=(int)request()->integer('page',1); $perPage=10; $items=new LengthAwarePaginator($vehicles->forPage($page,$perPage)->values(),$vehicles->count(),$perPage,$page,['path'=>request()->url(),'query'=>request()->query()]); $gallery=app(VehicleGalleryService::class); $items->getCollection()->each(function (KendaraanPelanggan $vehicle) use ($gallery): void { $mobil=$vehicle->penjualan?->mobil; $purchasedColor=$vehicle->pesanan?->snapshot_warna ?: $vehicle->warna; $selected=$mobil ? $gallery->forColor($mobil,$purchasedColor) : []; if (!$selected && !$purchasedColor && $mobil) $selected=$gallery->for($mobil)[$gallery->defaultColor($mobil)] ?? []; $vehicle->setAttribute('presentation_image',$selected['images'][0]['src'] ?? asset('assets/images/hero/yza-hero-reference-v3.png')); $vehicle->setAttribute('is_verified_ownership',true); }); $hasVerifiedPurchase=$vehicles->isNotEmpty(); return view('pelanggan.kendaraan.index',compact('items','hasVerifiedPurchase')); }
 public function create(): View { return view('pelanggan.kendaraan.create',['item'=>new KendaraanPelanggan(['kilometer'=>0])]); }
 public function store(StoreKendaraanPelangganRequest $request, MasterAuditService $audit): RedirectResponse { $p=$this->customer(); $item=$p->kendaraan()->create($request->validated()+['status'=>'aktif']); $audit->record('create','kendaraan_pelanggan',$item->id_kendaraan_pelanggan,'Pelanggan menambahkan kendaraan'); return redirect()->route('pelanggan.kendaraan.show',$item)->with('success','Kendaraan berhasil ditambahkan.'); }
 public function show(KendaraanPelanggan $kendaraan, VehicleGalleryService $gallery): View { $p=$this->customer(); abort_unless((int)$kendaraan->id_pelanggan===(int)$p->id_pelanggan,404); $kendaraan->load(['penjualan.mobil','pesanan']); $mobil=$kendaraan->penjualan?->mobil; $purchasedColor=$kendaraan->pesanan?->snapshot_warna ?: $kendaraan->warna; $selected=$mobil ? $gallery->forColor($mobil,$purchasedColor) : []; if (!$selected && !$purchasedColor && $mobil) $selected=$gallery->for($mobil)[$gallery->defaultColor($mobil)] ?? []; $verifiedOwnership=app(\App\Services\VerifiedCarOwnershipService::class)->vehicleBelongsToVerifiedPurchase((int)$p->id_pelanggan,(int)$kendaraan->id_kendaraan_pelanggan); $serviceCount=(int)$kendaraan->servis()->count(); $terminal=['selesai','ditolak','dibatalkan','kadaluarsa','expired']; $upcomingBooking=$kendaraan->bookingServis()->with('jenisServis')->whereDate('tanggal','>=',now()->toDateString())->whereNotIn('status',$terminal)->orderBy('tanggal')->orderBy('jam')->first(); $vehicleImage=$selected['images'][0]['src'] ?? asset('assets/images/hero/yza-hero-reference-v3.png'); $vehicleImageLabel=$selected['label'] ?? ($purchasedColor ?: 'Kendaraan Anda'); return view('pelanggan.kendaraan.show',compact('kendaraan','vehicleImage','vehicleImageLabel','verifiedOwnership','serviceCount','upcomingBooking')); }
 public function edit(KendaraanPelanggan $kendaraan, VehicleGalleryService $gallery): View { $p=$this->customer(); abort_unless((int)$kendaraan->id_pelanggan===(int)$p->id_pelanggan && $kendaraan->status==='aktif',404); $kendaraan->load(['penjualan.mobil','pesanan']); $mobil=$kendaraan->penjualan?->mobil; $purchasedColor=$kendaraan->pesanan?->snapshot_warna ?: $kendaraan->warna; $selected=$mobil ? $gallery->forColor($mobil,$purchasedColor) : []; if (!$selected && !$purchasedColor && $mobil) $selected=$gallery->for($mobil)[$gallery->defaultColor($mobil)] ?? []; $vehicleImage=$selected['images'][0]['src'] ?? asset('assets/images/hero/yza-hero-reference-v3.png'); return view('pelanggan.kendaraan.edit',['item'=>$kendaraan,'vehicleImage'=>$vehicleImage]); }
 public function update(UpdateKendaraanPelangganRequest $request, KendaraanPelanggan $kendaraan, MasterAuditService $audit): RedirectResponse { $p=$this->customer(); abort_unless((int)$kendaraan->id_pelanggan===(int)$p->id_pelanggan && $kendaraan->status==='aktif',404); $kendaraan->update($request->validated()); $audit->record('update','kendaraan_pelanggan',$kendaraan->id_kendaraan_pelanggan,'Pelanggan memperbarui kendaraan'); return redirect()->route('pelanggan.kendaraan.show',$kendaraan)->with('success','Kendaraan berhasil diperbarui.'); }
 public function deactivate(KendaraanPelanggan $kendaraan, MasterAuditService $audit): RedirectResponse { $p=$this->customer(); abort_unless((int)$kendaraan->id_pelanggan===(int)$p->id_pelanggan && $kendaraan->status==='aktif',404); $kendaraan->update(['status'=>'nonaktif']); $audit->record('status','kendaraan_pelanggan',$kendaraan->id_kendaraan_pelanggan,'Pelanggan menonaktifkan kendaraan'); return back()->with('success','Kendaraan dinonaktifkan.'); }
}
